export function Ssg({
  pageCount = "{{pageCount}}",
  accent = "{{accent}}",
  showBuildTime = {{showBuildTime}},
  siteName = "{{siteName}}",
}) {
  const times = { "10": "~1s", "100": "~8s", "1000": "~70s" };
  return (
    <div role="img" aria-label={`${siteName}, ${pageCount} pages generated at build time`} style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 16, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 12px", fontFamily: "ui-monospace, monospace", fontSize: 11, color: "#24143099" }}>{siteName}</p>
      <div style={{ padding: 12, borderRadius: 8, background: accent, fontSize: 11, fontWeight: 700, textAlign: "center" }}>
        Build: generate {pageCount} HTML files
        {showBuildTime && <small style={{ display: "block", marginTop: 4, fontWeight: 400 }}>{times[pageCount]}</small>}
      </div>
      <span aria-hidden="true" style={{ display: "block", textAlign: "center", fontSize: 16, color: "#24143060", margin: "8px 0" }}>&darr;</span>
      <div style={{ padding: 12, borderRadius: 8, background: "#24143010", fontSize: 11, textAlign: "center" }}>Request: served instantly from a CDN edge &mdash; ~5ms, no server work</div>
    </div>
  );
}
